SELECT d.institution_id,d.id,NULL,'Sistemática',13,'2ª série','Referencial Curricular do Ensino Médio de MS (2012) — catálogo revisado' FROM pedagogical_disciplines d WHERE d.name='Biologia' AND d.stage='Ensino Médio' ON CONFLICT DO NOTHING;
